        if (n == 2) return 1;

        // If the value of n is previously calculated 
      	// then return it here
        if (memo[n] != -1) return memo[n];

        // countDer(n) = (n-1)[countDer(n-1) + der(n-2)]
        return memo[n] = (n - 1) * (calculate(n - 1, memo) 
                                    + calculate(n - 2, memo));
