            C++

    #include <iostream>
using namespace std;

int derangeCount(int n) {

    // Create a DP array to store
  	// results
    vector<int> dp(n + 1);

    // Base cases
    dp[1] = 0;
    dp[2] = 1;

    // Fill the DP array using the recursive relation
    for (int i = 3; i <= n; i++) {
        dp[i] = (i - 1) * (dp[i - 1] + dp[i - 2]);
    }

    return dp[n];
}

int main() {
    int n = 5;
    cout << derangeCount(n); 
    return 0;
}


