    #include <iostream>
using namespace std;

int derangeCount(int n) {

    // Base cases
    if (n == 1) return 0;
    if (n == 2) return 1;

    // Variables to store previous two results
  	// Equivalent to dp[1]
    int prev2 = 0; 

  	// Equivalent to dp[2]
    int prev1 = 1; 

    // Calculate derangements using the optimized 
  	// space approach
    for (int i = 3; i <= n; i++) {
        int curr = (i - 1) * (prev1 + prev2);
        prev2 = prev1;
        prev1 = curr;
    }

    return prev1;
}

int main() {
    int n = 5;
    cout << derangeCount(n);
    return 0;
}


